Object pooling reuses objects instead of creating and destroying them, reducing garbage collection.

class BulletPool:
    def __init__(self, size):
        self.pool = [Bullet() for _ in range(size)]
        self.active = []

    def get(self):
        if self.pool:
            bullet = self.pool.pop()
            self.active.append(bullet)
            return bullet
        return None  # pool exhausted

    def recycle(self, bullet):
        self.active.remove(bullet)
        bullet.reset()
        self.pool.append(bullet)

